<?php
    require_once(dirname(__FILE__) . "/GetYearHandler.php");

    class UpdateYearHandler extends Handler {
        public function handle($input, $roles) {
            global $yearService, $databaseProvider;

            $response = (new GetYearHandler())
                ->handle(array(
                    "year" => $input["year"]), $roles);                    
            if ($response["code"] != 200) {
                return $response;
            }     

            $yearService->updateYearMainHighlight($input["year"], $input["mainHighlightId"]);
            $databaseProvider->materializeViews();
    
            return (new GetYearHandler())
                ->handle(array(
                    "year" => $input["year"]), $roles);
        }

        public function getRequiredRole() {
            return "ADMIN";
        }
        
        public function isProtected() {
            return TRUE;
        }

        public function getTag() {
            return "Years";
        }

        public function getPath() {
            return "/years/{year}";
        }

        public function getParameters() {
            return array(
                $this->createPathParameter("year", "integer", 2021));
        }

        public function getMethod() {
            return "PATCH";
        }
        
        public function getShortDescription() {
            return "Update a year with the specified identifier";
        }
        
        public function getLongDescription() {
            return "Updates a year with the specified identifier.";
        }
        
        public function getRequestExamples() {
            return array(
                $this->createRequestExample("Update year main highlight", '{"mainHighlightId":1}'));
        }

